 	upi_value=src.match(/upi_value' : "([^"]+)"/)[1];
 	quite_time=src.match(/quite_time' : "([^"]+)"/)[1];
 	cookies="";
 	function setCookie(cookie_name,value,cookie_time){
    var exdate=new Date();
    exdate.setTime(exdate.getTime()+(cookie_time*1000));
    cookies+=cookie_name+ "=" +escape(value)+((cookie_time==null) ? "" : "; path=/; expires="+exdate.toGMTString());
  }
  setCookie(uid_name,uid_value,quite_time);
  setCookie(upi_name,upi_value,quite_time);
result=java.ajax(baseUrl+','+JSON.stringify({"headers":{"cookie":String(cookies)}}))}
else{result=src}

