ruleToc.chapterList:
data.chapterListWithVolume[*].*
@js:
function deviceType() {
  try {
    return!!java.androidId();
  } catch (e) {
    return false;
  }
}
let device = deviceType()? 'android' : 'ios';
let genreValue = JSON.parse(java.ajax(book.bookUrl)).genre;
var datadist = {
  "-1": "纯净阅读",
  "-2": "纯净漫画",
  "51": "多人发音",
  "0": "真人发音",
  "1": "甜美少女",
  "2": "清亮青叔",
  "5": "开朗青年",
  "6": "温柔淑女",
  "4": "成熟大叔",
  "74": "大叔升级"
};
var ms = String(source.getVariable())
if (genreValue === '0' && ms === '-1') {
	if (device === 'android') {
    book.type = 8;} else {
    	book.type = 0;
    	}
} else if (genreValue === '1') {
	  var ms = '-2';
	  source.setVariable('-2');
	  if (device === 'android') {
    book.type = 64;} else {
    	book.type = 2;
    	}
}else if (genreValue === '4') {
	   var ms = '0';
	   if (device === 'android') {
    book.type = 32;} else {
    	book.type = 1;
    	}
} else if (genreValue === '9999'){
   	var ms = '-1';
   	if (device === 'android') {
    book.type = 8;} else {
    	book.type = 0;
    	}
	 } else {
	 	if (device === 'android') {
    book.type = 32;} else {
    	book.type = 1;
    	}
	 	};

var tishi = '\n\n当前模式：'+datadist[ms]+'\n\n如切换,请切换请下拉刷新详情页\n由于缓存原因，已听的需要切换到下一章再切回来'
java.toast(tishi);
result

ruleToc.nextTocUrl:
@js:
var next=[],
regex=/(pageNum=)(\d+)/,
num=baseUrl.match(regex)[2],
page=JSON.parse(src).totalPage;
if(page>num){
	for(i=1;i<=page;i++){
		url=baseUrl.replace(regex,
			`$1${i}`);
			next.push(url);
		}
	next
	}

