@js:
var url=source.getKey();
var flx=url+"/fenlei/";
var html=java.ajax(flx);
var h=org.jsoup.Jsoup.parse(html);
var a=h.select('.toplist li a');
var list=[];
for(i in a){
	var text=a[i].text();
	var href=a[i].attr("href");
	href=String(href).replace(/$/,"<,index_{{page}}.html>");
	var add=text+"::"+href;
	list.push(add);
	}
	list.join("&&");

